import React from "react";
import type { HeadFC, PageProps } from "gatsby";

import Layout from "../components/Layout";
import { TermsX } from "../ppm/primitives/legal/legal-x";

/**
 * Terms of Service.
 *
 * The document itself is data: see primitives/legal/terms-content.ts. That is
 * the only file to touch when the client's approved wording arrives.
 */
export default function TermsPage(_props: PageProps) {
  return (
    <Layout>
      <TermsX />
    </Layout>
  );
}

export const Head: HeadFC = () => (
  <>
    <title>Terms of Service | Kelley Road Property Management</title>
    <meta
      name="description"
      content="The terms covering use of the Kelley Road Property Management website, its property information and enquiries sent through it."
    />
    {/* The wording on this page is still a template rather than the client's
        approved copy, so it is kept out of search results until it is real.
        Delete this line at the same time as the notice in the content file. */}
    <meta name="robots" content="noindex, follow" />
  </>
);
